// Radiant action lines popping out from the button left and right sides
const ActionLines: React.FC<{ side: "left" | "right"; progress: number }> = ({
  side,
  progress,
}) => {
  if (progress <= 0 || progress >= 1) return null;

  const lineTranslate = interpolate(progress, [0, 1], [0, 18]);
  const lineOpacity = interpolate(progress, [0.7, 1], [1, 0]);
  const scale = interpolate(progress, [0, 0.2, 1], [0, 1.2, 0.8]);

  const isLeft = side === "left";

  return (
    <div
      style={{
        position: "absolute",
        width: 80,
        height: 80,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        transform: `scale(${scale})`,
        opacity: lineOpacity,
        pointerEvents: "none",
        transition: "none",
      }}
    >
      <svg viewBox="-40 -40 80 80" style={{ width: "100%", height: "100%" }}>
        {[-32, 0, 32].map((angle, idx) => {
          const finalAngle = isLeft ? angle + 180 : angle;
          const rad = (finalAngle * Math.PI) / 180;

          const startDist = 12 + lineTranslate;
          const endDist = 30 + lineTranslate;

          const x1 = startDist * Math.cos(rad);
          const y1 = startDist * Math.sin(rad);
          const x2 = endDist * Math.cos(rad);
          const y2 = endDist * Math.sin(rad);

          return (
            <line
              key={idx}
              x1={x1}
              y1={y1}
              x2={x2}
              y2={y2}
              stroke="#0095f6"
              strokeWidth="4"
              strokeLinecap="round"
            />
          );
        })}
      </svg>
    </div>
  );
};

// Vibrant deterministic confetti explosion component triggered at button click frame (73)
const Confetti: React.FC<{ frame: number; fps: number; width: number; height: number }> = ({
  frame,
  fps,
  width,
  height,
}) => {
  const triggerFrame = 73;
  const t = frame - triggerFrame;

  if (t < 0) return null;

  const NUM_CONFETTI = 80;
  const CONFETTI_COLORS = [
    "#ff0a54",
    "#ff477e",
    "#ff7096",
    "#ff85a1",
    "#fbb1bd",
    "#f9bec7",
    "#3f37c9",
    "#4895ef",
    "#4cc9f0",
    "#f72585",
    "#7209b7",
    "#ffd166",
    "#06d6a0",
    "#118ab2",
  ];

  const x0 = width / 2;
  const y0 = height / 2 + 185; // Button location center

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        pointerEvents: "none",
        zIndex: 50,
        overflow: "hidden",
      }}
    >
      {Array.from({ length: NUM_CONFETTI }).map((_, i) => {
        // High fidelity deterministic physics attributes
        const angle = -Math.PI * (0.15 + random(`angle-${i}`) * 0.7);
        const velocity = 15 + random(`velocity-${i}`) * 25;
        const color = CONFETTI_COLORS[Math.floor(random(`color-${i}`) * CONFETTI_COLORS.length)];
        const size = 10 + random(`size-${i}`) * 14;
        const gravity = 0.4 + random(`gravity-${i}`) * 0.3;
        const drag = 0.92 + random(`drag-${i}`) * 0.04;
        const rotationSpeed = (random(`rot-${i}`) - 0.5) * 10;
        const shape = random(`shape-${i}`) > 0.4 ? "rect" : "circle";
        const tiltAngle = random(`tilt-${i}`) * 360;

        // Physics equations using exact analytical drag updates
        const xDist = (velocity * (1 - Math.pow(drag, t))) / (1 - drag);
        const yDist = (velocity * (1 - Math.pow(drag, t))) / (1 - drag);

        const px = x0 + Math.cos(angle) * xDist;
        const py = y0 + Math.sin(angle) * yDist + 0.5 * gravity * t * t;

        // Smooth fade out after lifespan
        const opacity = interpolate(t, [30, 50], [1, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        if (opacity <= 0) return null;

        const rotation = tiltAngle + t * rotationSpeed;

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: px,
              top: py,
              width: size,
              height: shape === "rect" ? size * 0.6 : size,
              backgroundColor: color,
              borderRadius: shape === "circle" ? "50%" : 4,
              transform: `translate(-50%, -50%) rotate(${rotation}deg)`,
              opacity: opacity,
              transition: "none",
            }}
          />
        );
      })}
    </div>
  );
};

